using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Ring of Shooting Stars (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class RingOfShootingStars2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("ring-of-shooting-stars", null, 0, MagicItemType.Ring, ItemRarity.VeryRare, true, ContentSource.Srd51,
			Charges(6, ItemRecharge.LongRest, "1d6"),
			("Anello delle stelle cadenti", "Anello, molto raro (richiede sintonia in un luogo esterno di notte)",
			"Finché il personaggio indossa questo anello e si trova in un'area di luce fioca o oscurità, può lanciare con esso gli incantesimi *luci danzanti* e *luce* a volontà. Ognuno di questi incantesimi richiede un'azione per essere lanciato.\n\nL'anello possiede 6 cariche per le altre proprietà, descritte di seguito. All'alba di ogni giorno, l'anello recupera 1d6 cariche consumate.\n\n***Luminescenza.*** Il personaggio può usare un'azione per consumare 1 carica e lanciare l'incantesimo *luminescenza* con l'anello.\n\n***Sfera di fulmini.*** Il personaggio può consumare 2 cariche usando un'azione per creare da una a quattro sfere di fulmini del diametro di 90 cm. Maggiore è il numero delle sfere create, minore è la potenza di ogni singola sfera.\n\nOgni sfera compare in uno spazio libero che il personaggio è in grado di vedere entro 36 metri da lui, e dura finché il personaggio si concentra (come se si concentrasse su un incantesimo), fino a un massimo di 1 minuto. Ogni sfera emana luce fioca in un raggio di 9 metri.\n\nCome azione bonus, il personaggio può muovere ogni sfera fino a 9 metri, ma mai a più di 36 metri da sé. Quando una creatura che non sia il personaggio giunge entro 1,5 metri da una sfera, questa scarica un fulmine contro quella creatura e scompare. La creatura deve superare un tiro salvezza su Destrezza con CD 15, altrimenti subisce un ammontare di danni da fulmine dipendente dal numero delle sfere che il personaggio ha creato.\n\n| Sfere | Danni da fulmine |\n|---|---|\n| 4 | 2d4 |\n| 3 | 2d6 |\n| 2 | 5d4 |\n| 1 | 4d12 |\n\n***Stelle cadenti.*** Il personaggio può consumare da 1 a 3 cariche usando un'azione. Per ogni carica consumata, il personaggio lancia dall'anello un frammento di luce scintillante verso un punto che è in grado di vedere situato entro 18 metri da lui. Ogni creatura che si trova all'interno di un cubo con spigolo di 4,5 metri originato da quel punto viene inondata di scintille e deve effettuare un tiro salvezza su Destrezza con CD 15: subisce 5d4 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo.", null),
			("Ring of Shooting Stars", "Ring, very rare (requires attunement outdoors at night)",
			"While wearing this ring in dim light or darkness, you can cast dancing lights and light from the ring at will. Casting either spell from the ring requires an action.\n\nThe ring has 6 charges for the following other properties. The ring regains 1d6 expended charges daily at dawn.\n\n***Faerie Fire.*** You can expend 1 charge as an action to cast faerie fire from the ring.\n\n***Ball Lightning.*** You can expend 2 charges as an action to create one to four 3-foot-diameter spheres of lightning. The more spheres you create, the less powerful each sphere is individually.\n\nEach sphere appears in an unoccupied space you can see within 120 feet of you. The spheres last as long as you concentrate (as if concentrating on a spell), up to 1 minute. Each sphere sheds dim light in a 30-foot radius.\n\nAs a bonus action, you can move each sphere up to 30 feet, but no farther than 120 feet away from you. When a creature other than you comes within 5 feet of a sphere, the sphere discharges lightning at that creature and disappears. That creature must make a DC 15 Dexterity saving throw. On a failed save, the creature takes lightning damage based on the number of spheres you created.\n\n| Spheres | Lightning Damage |\n|---|---|\n| 4 | 2d4 |\n| 3 | 2d6 |\n| 2 | 5d4 |\n| 1 | 4d12 |\n\n***Shooting Stars.*** You can expend 1 to 3 charges as an action. For every charge you expend, you launch a glowing mote of light from the ring at a point you can see within 60 feet of you. Each creature within a 15-foot cube originating from that point is showered in sparks and must make a DC 15 Dexterity saving throw, taking 5d4 fire damage on a failed save, or half as much damage on a successful one.", null));
	}
}
